import json,urllib.request,importlib.metadata
from concurrent.futures import ThreadPoolExecutor
def check(kv):
 k,ver=kv
 with urllib.request.urlopen("https://pypi.org/pypi/"+k+"/"+ver+"/json") as f:v=json.load(f)
 try:installed=importlib.metadata.version(k)
 except importlib.metadata.PackageNotFoundError:installed=None
 return {"package":k,"requested":ver,"official_version":v["info"]["version"],"requires_python":v["info"].get("requires_python"),"wheel_count":sum(f["packagetype"]=="bdist_wheel" for f in v["urls"]),"current_installed":installed}
print(json.dumps(list(ThreadPoolExecutor(4).map(check,[("Pillow","12.3.0"),("h5py","3.16.0"),("numpy","2.5.3"),("soundfile","0.13.1")])),indent=2))
